class Solution {
    public boolean validPath(int n, int[][] edges, int source, int destination) {
        List<List<Integer>> graph = new ArrayList<>();      // graph.get(u) 是 u 的所有邻居
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] e : edges) {
            graph.get(e[0]).add(e[1]);                      // 无向图：两个方向都要加
            graph.get(e[1]).add(e[0]);
        }
        boolean[] seen = new boolean[n];
        seen[source] = true;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(source);
        while (!stack.isEmpty()) {
            int u = stack.pop();
            if (u == destination) {
                return true;
            }
            for (int v : graph.get(u)) {                    // 只看和 u 相连的点
                if (!seen[v]) {
                    seen[v] = true;
                    stack.push(v);
                }
            }
        }
        return false;
    }
}

