func validPath(n int, edges [][]int, source int, destination int) bool {
	graph := make([][]int, n) // graph[u] 是 u 的所有邻居
	for _, e := range edges {
		graph[e[0]] = append(graph[e[0]], e[1]) // 无向图：两个方向都要加
		graph[e[1]] = append(graph[e[1]], e[0])
	}
	seen := make([]bool, n)
	seen[source] = true
	stack := []int{source}
	for len(stack) > 0 {
		u := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if u == destination {
			return true
		}
		for _, v := range graph[u] { // 只看和 u 相连的点
			if !seen[v] {
				seen[v] = true
				stack = append(stack, v)
			}
		}
	}
	return false
}

