        const n = a.n, g = Array.from({ length: n }, () => []), seen = new Array(n).fill(false), st = [];
        const edgeKey = (u, v) => (u < v ? `${u},${v}` : `${v},${u}`);
        const treeEdges = new Set();
        let built = 0, cur = -1, hotEdge = -1, activeEdges = new Set(), freshChips = new Set(), seenCount = 0;
        const view = () => [
