            })),
            edges: a.edges.map(([u, v], k) => {
              const key = edgeKey(u, v);
              const cls = hotEdge >= 0
                ? (k === hotEdge ? "on draw" : k < built ? "" : "dim")
                : (activeEdges.has(key) ? "on draw" : treeEdges.has(key) ? "on" : "");
              return [u, v, cls];
            }),
          },
