        seen[a.source] = true; seenCount = 1; st.push(a.source);
        snap("出发", `从 ${a.source} 出发：标记走过，放进栈。要找的是 ${a.destination}。`, view(), {
          at: "start",
          facts: [["当前点", a.source], ["已访问", 1, 0], ["栈大小", st.length, 0]],
