class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]       # 上下左右
        ans = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0:
                    continue
                for di, dj in dirs:
                    a, b = i + di, j + dj               # 邻居的坐标
                    if not (0 <= a < m and 0 <= b < n) or grid[a][b] == 0:     # 出界或者是水
                        ans += 1                        # 这条边是周长
        return ans

