class Solution {
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};    // 上下左右

    public int islandPerimeter(int[][] grid) {
        int m = grid.length, n = grid[0].length, ans = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    continue;
                }
                for (int[] d : DIRS) {
                    int a = i + d[0], b = j + d[1];         // 邻居的坐标
                    if (a < 0 || a >= m || b < 0 || b >= n || grid[a][b] == 0) {    // 出界或者是水
                        ans++;                              // 这条边是周长
                    }
                }
            }
        }
        return ans;
    }
}

